//! Write the generated dispatch into the driver's tree.
//!
//! The `.inc` precedent, one layer down: `model`'s `emit-cuda` writes
//! the static class traces into `driver-cuda/csrc`, and this writes the
//! per-symbol binding the same way — a committed file, regenerated by a
//! command, with a test that fails when the two drift.
//!
//! Committed rather than built by `build.rs` for the reason the traces
//! are: the file is C++ a reader has to be able to open, and a
//! generated header that only exists inside `target/` is one nobody
//! reviews. The diff IS the review.
//!
//! Run: `cargo run -p kernels-cuda --bin emit-dispatch`

fn main() {
    let out = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../driver-cuda/csrc/src/model/declared/generated_dispatch.inc"
    );
    // Every table, because the dispatch is not a family's: a row that
    // states its sources is bound here whoever states the symbol.
    let text = kernels_cuda::abi::emit_dispatch(
        &[
            kernels_cuda::attn::KERNELS,
            kernels_cuda::gemm::KERNELS,
            kernels_cuda::layout::KERNELS,
            kernels_cuda::mlp::KERNELS,
            kernels_cuda::moe::KERNELS,
            kernels_cuda::norm::KERNELS,
            kernels_cuda::quant::KERNELS,
            kernels_cuda::rope::KERNELS,
            kernels_cuda::sample::KERNELS,
            kernels_cuda::ssm::KERNELS,
        ],
        "c",
    );
    std::fs::write(out, text).unwrap_or_else(|e| panic!("cannot write {out}: {e}"));
    eprintln!("wrote {out}");
}
